package edu.team12.deadlocklab.detection;
import edu.team12.deadlocklab.domain.*;import java.util.*;
public final class MatrixDetector {
 public DetectionResult detect(Scenario s){List<String>errors=ScenarioValidator.errors(s);if(!errors.isEmpty())throw new IllegalArgumentException(String.join("; ",errors));int n=s.processes().size();List<Integer>work=new ArrayList<>(s.available());boolean[]finish=new boolean[n];for(int i=0;i<n;i++)finish[i]=s.terminated().contains(s.processes().get(i))||s.allocation().get(i).stream().allMatch(x->x==0);List<DetectionResult.Step>trace=new ArrayList<>();boolean progress;
  do{progress=false;for(int i=0;i<n;i++)if(!finish[i]){List<Boolean>fits=new ArrayList<>();boolean eligible=true;for(int j=0;j<s.resources().size();j++){boolean b=s.request().get(i).get(j)<=work.get(j);fits.add(b);eligible&=b;}List<Integer>before=List.copyOf(work),released=eligible?s.allocation().get(i):Collections.nCopies(work.size(),0);if(eligible)for(int j=0;j<work.size();j++)work.set(j,work.get(j)+released.get(j));trace.add(new DetectionResult.Step(s.processes().get(i),before,s.request().get(i),fits,eligible,released,List.copyOf(work),eligible?"eligible; simulate completion":"request exceeds Work; remains unfinished"));if(eligible){finish[i]=true;progress=true;}}}while(progress);List<String>d=new ArrayList<>();for(int i=0;i<n;i++)if(!finish[i])d.add(s.processes().get(i));return new DetectionResult(d,trace,work);}
}
